      SUBROUTINE FIX8HCC     REVISE REFERENCES FOR MISALIGNMENTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'LIMITS.CIN'CC     LOCAL VARIABLESC      INTEGER         TYPET      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATACC------------------------------------------------------------------------C      NN = NUMC   10 NN = NN + 1      III = ISTOR(NN)      TYPET = IDATA(III)      IF (TYPET .LE. 0 .OR. TYPET .GE. 50) GO TO 6000      IF (TYPET .EQ. 8) GO TO 800      GO TO 6000CC      8. -- MISALIGNMENTC  800 KREG = IDATA(III+9)      KTIE = TIE(III+9)      IF (KREG .EQ. NUM .AND. KTIE .NE. 100) THEN        KREG = NEL      ENDIF      LAKE = KREG      DATA(III+9) = FAKE      GO TO 6000C 6000 IF (NN .LT. NELLIM) GO TO 10C 6200 RETURN      END